"""Protocol rules that a machine can decide, shared by the edit-time hook
(.claude/hooks/guard.py) and the commit-time gate (validate.py, .githooks/pre-commit).

Each function takes parsed documents or file text and returns a list of violations.
"""
import json

# Generated by render.py; render.py asserts its VIEWS match this set.
GENERATED = {"bibliography.md", "concept-map.md", "claims.md", "phenomena.md"}

# Whole-file dump layout, or the list keys written one record per line.
LAYOUT = {
    "bibliography": "indent1", "concepts": "indent1", "phenomena": "indent1",
    "claims": ["claims", "master_relations"], "debates": ["debates"],
    "tasks": ["tasks"], "experiments": ["experiments"],
}

# Statuses a new claim may enter with. Anything else, and any change of status, is the human gate.
ENTRY_STATUSES = {"new", "conjecture", "test", "definition"}

# Files whose reading makes an agent non-blind to the formalism (AGENTS.md phenomena protocol).
FORMALISM_FILES = ("program/spine.md", "program/formalization.md", "explorations/grounded-misprision-program.md", "program/data/claims.json")


def layout_errors(name, text):
    """The layout program/data/<name>.json must keep. Assumes `text` parses."""
    spec = LAYOUT.get(name)
    if spec is None:
        return []
    doc = json.loads(text)
    if spec == "indent1":
        if text != json.dumps(doc, indent=1, ensure_ascii=False):
            return [f"{name}.json: layout changed; it must equal json.dumps(d, indent=1, ensure_ascii=False) with no trailing newline"]
        return []
    errs = [] if text.endswith("\n") else [f"{name}.json: missing trailing newline"]
    lines = set(text.split("\n"))
    for key in spec:
        recs = doc.get(key, [])
        for i, r in enumerate(recs):
            want = "    " + json.dumps(r, ensure_ascii=False) + ("," if i < len(recs) - 1 else "")
            if want not in lines:
                errs.append(f"{name}.json: {key} record {r.get('id', i)} is not on one line as json.dumps(record, ensure_ascii=False)")
                break
    return errs


def claim_status_changes(old_doc, new_doc):
    """[(id, old status or None, new status)] for every status the human gate must approve."""
    old = {c["id"]: c.get("status") for c in old_doc.get("claims", [])}
    out = []
    for c in new_doc.get("claims", []):
        before = old.get(c["id"])
        if c["id"] not in old:
            if c.get("status") not in ENTRY_STATUSES:
                out.append((c["id"], None, c.get("status")))
        elif before != c.get("status"):
            out.append((c["id"], before, c.get("status")))
    return out


def _assessed(p):
    return any(a.get("verdict") != "untested" for a in p.get("assessments", []))


def phenomena_violations(old_doc, new_doc):
    """Frozen wording and logged verdict changes, comparing a baseline with a new version."""
    old = {p["id"]: p for p in old_doc.get("phenomena", [])}
    errs = []
    for p in new_doc.get("phenomena", []):
        before = old.get(p["id"])
        if before is None:
            continue
        if _assessed(before) and p.get("behavior") != before.get("behavior"):
            errs.append(f"phenomenon {p['id']}: behavior is frozen once assessed; file the reworded behavior under a new id")
        prev = {a["formalism"]: a for a in before.get("assessments", [])}
        for a in p.get("assessments", []):
            b = prev.get(a["formalism"])
            if b is None or b.get("verdict") == a.get("verdict") or b.get("verdict") == "untested":
                continue
            if a.get("derivation") == b.get("derivation") or a.get("notes") == b.get("notes"):
                errs.append(f"phenomenon {p['id']}: verdict {b['verdict']} -> {a['verdict']} for {a['formalism']} "
                            "needs a changed derivation and a note saying why")
    return errs


def blind_additions(old_doc, new_doc):
    """Ids that gain provenance.blind = true in the new version."""
    old = {p["id"]: p.get("provenance", {}).get("blind", False) for p in old_doc.get("phenomena", [])}
    return [p["id"] for p in new_doc.get("phenomena", [])
            if p.get("provenance", {}).get("blind") is True and old.get(p["id"]) is not True]
